// F5M S/R Levels [TickSniper] — OpenScript port of "F5M SR Levels.pine" v4.0
//
// Takes the opening window's high/low for the session and projects fixed
// percentage resistance/support levels plus 25/50/75 equilibrium levels from it.
//
// CONVERSION NOTES — where this differs from the Pine, and why.
//
// 1. No request.security. The Pine reads the first completed bar of the session
//    at a chosen base timeframe. This derives the same window from the bar
//    clock instead: `sessionStart` + `windowMin` in IST minutes. The engine's
//    calendar context (hour/minute) is IST, so 555 = 09:15 for NSE.
//    This is not only a simplification. The server-side compiler does not
//    implement request.security, so a script using it saves with no compiled IR
//    and can never be added to a chart or restored into a layout. Avoiding it is
//    what makes this port usable end to end.
//    NO BASE-TIMEFRAME DROPDOWN. The Pine offers one (30s..2h) and this cannot:
//    converting a chosen timeframe into a bar count needs the CHART's own
//    interval, and v1 gives a script no way to read it — there is no
//    `syminfo.interval`, and `request.security` (which is how the Pine learns
//    it) is not implemented server-side. `windowBars` is that dropdown expressed
//    in the one unit a script can actually count.
//    MAPPING: the Pine's "Base Timeframe (F5M TF)" becomes `windowBars` — the
//    number of CHART BARS the opening window spans. `windowBars = 1` is exactly
//    the Pine's "Chart" setting: the session's first candle. For the Pine
//    default of "5" (the first 5-minute candle), set `windowBars` to 5 on a
//    1-minute chart, or leave it at 1 on a 5-minute chart.
//    Counted in bars, not minutes, deliberately: a minute window over-captures
//    whenever the chart interval does not divide it. On a 3-minute chart a
//    "first 5 minutes" window admits the bar starting at 09:18, which covers
//    09:18-09:21, so the capture silently spans six minutes. Verified against
//    real NIFTY bars at 1m/3m/5m/15m.
//
// 2. Drawing model. The Pine creates a line per level, pushes its right edge
//    forward on every bar, then on the next day's first bar snaps x2 back to the
//    previous day's last bar — so each session's levels are bounded to their own
//    session and the live one keeps growing. OpenScript drawing streams are
//    declarative: one confirmed bar spawns one object, and
//    `extend=extend.until, terminate=terminate.new_session` closes it on the LAST
//    bar of the session it spawned in. That is the same bound, reached by
//    declaration instead of by bookkeeping.
//    ONE output covers both of the Pine's cases. The predicate needs a following
//    bar in a different calendar day, so it can never hold on the final loaded
//    bar: the current session's object stays open and rides the live edge, while
//    every past session's object is closed at its own last bar. The session
//    calendar is resolved from the instrument at execution, so the same saved
//    indicator bounds to IST days on NSE and to the venue's days elsewhere.
//    `max_kept` is the single knob for how many sessions are retained. Like
//    Pine's own `max_lines_count` it is a declaration argument and must be a
//    compile-time constant (OS2023), so history depth is edited here rather than
//    exposed as an input.
//
// 3. Labels carry the level's own price via the `{price}` placeholder, which
//    lowers to a spawn-sampled template (design §11) formatted to 2 decimals.
//    The Pine also prints the percentage; that would need a second placeholder
//    bound to an input value, which the template surface does not offer, so the
//    percentage stays in the input name instead.
//    EVERY retained session is labelled, as the Pine labels every session it
//    draws. The port previously set `label_latest_only=true`, and that was a
//    consequence of the old lifetime model rather than a taste call: a level's
//    label is a RIGHT-EDGE tag anchored at x2, so while every retained object
//    rode to the live edge, all 20 sessions x 15 labels landed in one column and
//    only the newest was legible. Per-session termination gives each session its
//    own x2, so the tags now spread one column per session and the previous
//    sessions' S/R prices are readable again.
//
// 4. Two defects in the source Pine are NOT reproduced:
//    - its L5 label prints r4's price (`fmtLbl(r4, i_p5, "+")` at line 224)
//      while drawing the line at r5, so the top label reads the L4 price;
//    - its fifth percentage input is titled "Level 4 %", duplicating the fourth.
//
// 5. Alert messages carry no emoji, per the repository's plain-text rule.

indicator("F5M S/R Levels [TickSniper]", shorttitle="FTF S/R", overlay=true)

showBase = input.bool(true, "Show F5M High/Low Base", group="Visibility")
showEQ = input.bool(true, "Show Equilibrium Levels (25/50/75)", group="Visibility")
showUp = input.bool(true, "Show Resistance (Upside)", group="Visibility")
showDn = input.bool(true, "Show Support (Downside)", group="Visibility")

sessionHour = input.int(9, "Session start hour (IST)", minval=0, maxval=23, group="Calculation")
sessionMinute = input.int(15, "Session start minute (IST)", minval=0, maxval=59, group="Calculation")
windowBars = input.int(1, "Opening window (chart bars)", minval=1, maxval=120, group="Calculation")

p1 = input.float(0.1306, "Level 1 %", minval=0.0001, maxval=100, step=0.0001, group="Levels")
p2 = input.float(0.2611, "Level 2 %", minval=0.0001, maxval=100, step=0.0001, group="Levels")
p3 = input.float(0.5, "Level 3 %", minval=0.0001, maxval=100, step=0.0001, group="Levels")
p4 = input.float(0.7389, "Level 4 %", minval=0.0001, maxval=100, step=0.0001, group="Levels")
p5 = input.float(1.0, "Level 5 %", minval=0.0001, maxval=100, step=0.0001, group="Levels")

baseCol = input.color(#000000, "F5M Base H/L", group="Colors")
eq25Col = input.color(#ffeb3b, "Equilibrium 25%", group="Colors")
eq50Col = input.color(#9e9e9e, "Equilibrium 50%", group="Colors")
eq75Col = input.color(#ffeb3b, "Equilibrium 75%", group="Colors")
upCol1 = input.color(#00e5ff, "Resistance L1", group="Colors")
upCol2 = input.color(#00c853, "Resistance L2", group="Colors")
upCol3 = input.color(#76ff03, "Resistance L3", group="Colors")
upCol4 = input.color(#b9f6ca, "Resistance L4", group="Colors")
upCol5 = input.color(#800000, "Resistance L5", group="Colors")
dnCol1 = input.color(#ff9100, "Support L1", group="Colors")
dnCol2 = input.color(#ff1744, "Support L2", group="Colors")
dnCol3 = input.color(#d500f9, "Support L3", group="Colors")
dnCol4 = input.color(#7c4dff, "Support L4", group="Colors")
dnCol5 = input.color(#800000, "Support L5", group="Colors")
lw = input.int(1, "Line Width", minval=1, maxval=3, group="Colors")

// The opening window, counted in BARS from the session's first bar.
//
// Counting bars rather than minutes is what makes this exact on every chart
// interval. A minute window over-captures whenever the interval does not divide
// it: on a 3-minute chart a "first 5 minutes" window admits the bar starting at
// 09:18, which covers 09:18-09:21, so the capture silently spans six minutes.
// One bar is also precisely what the Pine reads when its base timeframe is set
// to "Chart".
// `newDay` is what makes this repeat: `inSession` is true for EVERY bar of a
// normal intraday feed (all of them are at or after the open), so keying the
// reset off `not inSession[1]` alone fires once for the whole dataset and only
// the first session ever spawns. The `not inSession[1]` arm is still needed for
// feeds that carry pre-open bars, where the day starts below `sessionStart`.
minuteOfDay = hour * 60 + minute
sessionStart = sessionHour * 60 + sessionMinute
inSession = minuteOfDay >= sessionStart
newDay = ta.change(dayofmonth) != 0
sessionFirstBar = inSession and (newDay or not inSession[1])

var barsIn = 0
barsIn := sessionFirstBar ? 1 : barsIn + 1

inWindow = inSession and barsIn <= windowBars
firstWindowBar = barsIn == 1
windowClosed = barsIn == windowBars + 1

// Running high/low across the window. `firstWindowBar` reseeds each session, so
// the value carried between sessions is never blended into the next one.
var winH = na
winH := firstWindowBar ? high : (inWindow ? math.max(winH, high) : winH)

var winL = na
winL := firstWindowBar ? low : (inWindow ? math.min(winL, low) : winL)

f5H = winH
f5L = winL
hlRange = f5H - f5L

r1 = f5H * (1 + p1 / 100)
r2 = f5H * (1 + p2 / 100)
r3 = f5H * (1 + p3 / 100)
r4 = f5H * (1 + p4 / 100)
r5 = f5H * (1 + p5 / 100)

s1 = f5L * (1 - p1 / 100)
s2 = f5L * (1 - p2 / 100)
s3 = f5L * (1 - p3 / 100)
s4 = f5L * (1 - p4 / 100)
s5 = f5L * (1 - p5 / 100)

eq25 = f5L + hlRange * 0.25
eq50 = f5L + hlRange * 0.5
eq75 = f5L + hlRange * 0.75

// Exactly once per session: `barsIn` is reseeded to 1 on the session's first bar
// and counts up from there, so `barsIn == windowBars + 1` is true on one bar of
// each session and no other.
spawn = windowClosed and not na(f5H) and not na(f5L)

plotlevel(spawn and showBase, f5H, "F5M High", color=baseCol, width=2, style=line.style_solid, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="High {price}")
plotlevel(spawn and showBase, f5L, "F5M Low", color=baseCol, width=2, style=line.style_solid, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="Low {price}")
plotlevel(spawn and showEQ, eq25, "EQ 25%", color=eq25Col, width=1, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="EQ25 {price}")
plotlevel(spawn and showEQ, eq50, "EQ 50%", color=eq50Col, width=1, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="EQ50 {price}")
plotlevel(spawn and showEQ, eq75, "EQ 75%", color=eq75Col, width=1, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="EQ75 {price}")
plotlevel(spawn and showUp, r1, "Resistance 1", color=upCol1, width=lw, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="R1 {price}")
plotlevel(spawn and showUp, r2, "Resistance 2", color=upCol2, width=lw, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="R2 {price}")
plotlevel(spawn and showUp, r3, "Resistance 3", color=upCol3, width=lw, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="R3 {price}")
plotlevel(spawn and showUp, r4, "Resistance 4", color=upCol4, width=lw, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="R4 {price}")
plotlevel(spawn and showUp, r5, "Resistance 5", color=upCol5, width=lw, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="R5 {price}")
plotlevel(spawn and showDn, s1, "Support 1", color=dnCol1, width=lw, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="S1 {price}")
plotlevel(spawn and showDn, s2, "Support 2", color=dnCol2, width=lw, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="S2 {price}")
plotlevel(spawn and showDn, s3, "Support 3", color=dnCol3, width=lw, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="S3 {price}")
plotlevel(spawn and showDn, s4, "Support 4", color=dnCol4, width=lw, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="S4 {price}")
plotlevel(spawn and showDn, s5, "Support 5", color=dnCol5, width=lw, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=20, label="S5 {price}")

alertcondition(not na(r1) and ta.crossover(close, r1), title="F5M R1 Crossed", message="Crossed Resistance L1")
alertcondition(not na(r4) and ta.crossover(close, r4), title="F5M R4 Crossed", message="Crossed Resistance L4")
alertcondition(not na(s1) and ta.crossunder(close, s1), title="F5M S1 Broken", message="Broke Support L1")
alertcondition(not na(s4) and ta.crossunder(close, s4), title="F5M S4 Broken", message="Broke Support L4")
